def single(id, skill, stem, options, runner, runnerWhy, think, eli5, learn):
    return dict(id=id, type="single", skill=skill, stem=stem, options=options, answer=0, runner=runner, runnerWhy=runnerWhy, think=think, eli5=eli5, learn=learn)

