GOAL = ("Agents must answer from current policy content held in an Azure AI Search index, a Blob container and OneLake. "
        "**Goal:** use only generally available features, and the agent must connect to the knowledge without storing keys.")
def S(i, sol, ans, prem, apply, rule):
    return dict(id="m1-s" + str(i), type="solution", skill=D2, scenario=GOAL, stem="**Proposed solution:** " + sol + " Does this meet the goal?", answer=ans,
                think=T(prem, [["Several sources, GA","Knowledge base","Extractive retrieval"],["Want a composed answer from the KB","Preview","Answer synthesis"],["User-uploaded files","Wrong tool","File search"]],
                        apply, rule, "Connect retrieval pipelines directly to workflows and agent tools."),
                eli5="The librarian may fetch pages from three shelves; writing the essay for you is still being tested.", learn=L+"agents/concepts/what-is-foundry-iq")
A += [
 S(1, "Create a knowledge base over the three sources with extractive retrieval, and connect the agent to its MCP endpoint using the project's managed identity.", True,
   "That multi-source retrieval must be preview. Knowledge bases with extractive retrieval over these sources are GA.",
   [["\"index, a Blob container and OneLake\"","All GA knowledge sources."],["\"project's managed identity\"","No keys: met."]], "GA knowledge base: extractive retrieval; agents connect over MCP with managed identity."),
 S(2, "Create the same knowledge base, enable answer synthesis, and connect with the project's managed identity.", False,
   "That synthesis is part of GA. It's still preview.",
   [["\"enable answer synthesis\"","Preview: not met."],["\"managed identity\"","Keyless: met, but the first half fails."]], "Answer synthesis and query planning are preview."),
 S(3, "Upload copies of all documents to a file search vector store attached to the agent.", False,
   "That file search serves organisational knowledge. It's for documents users provide, and copies go stale.",
   [["\"copies of all documents\"","Not current content."],["\"file search\"","Wrong tool for curated sources."]], "File search = user-provided files, not curated organisational content."),
]
